import { getProductBySlug } from "@/features/catalog/server/catalog-repository";

/**
 * GET /api/products/[slug]
 *
 * Demonstrates `RouteContext<"/api/products/[slug]">` — the route-handler
 * counterpart to `PageProps`/`LayoutProps`, generated by `next typegen`. The
 * route string is validated against the real route tree, and `params` is typed
 * from the actual `[slug]` segment.
 *
 * As with pages, `params` is a Promise in v16 and must be awaited.
 */
export async function GET(
  _request: Request,
  context: RouteContext<"/api/products/[slug]">,
) {
  const { slug } = await context.params;
  const product = await getProductBySlug(slug);

  if (!product) {
    // A route handler returns a real Response, so it controls its own status
    // directly — none of the PPR streaming caveats that make `notFound()` in a
    // page return 200 on a cold request apply here.
    return Response.json({ error: "Not found", slug }, { status: 404 });
  }

  return Response.json(product, {
    headers: {
      "Cache-Control": "public, s-maxage=900, stale-while-revalidate=86400",
    },
  });
}
